window.TEXTP["92.4"] = [[["p","282/30 — Первый аят:"],["p","Всевышний Аллах сказал: «Они (в своей земной жизни) исполняли обеты (которые они дали на повиновение Аллаху)», сура «Аль-Инсан»/7 аят."],["p","283/31 — Второй аят:"],["p","Всевышний Аллах сказал: «И что бы вы ни расходовали (в качестве милостыни) из средств [много или мало] (стремясь к довольству Аллаха), или какой бы обет вы ни дали [обязали самих себя сделать что-либо], то поистине, Аллах знает это (и воздаст по вашим намерениям)», сура «Аль-Бакара»/270 аят."],["p","284/32 — Третий аят:"],["p","Всевышний Аллах сказал: «И полностью выполнят свои обеты (которые они давали относительно жертвоприношений)», сура «Аль-Хадж»/29 аят."],["sc","img/word-92/image103.webp",305,502,"f"],["c","Книга Восполнения"],["h2","<b>Книга Восполнения (1)</b>"],["p","285/1 — Первый аят:"],["p","Всевышний Аллах сказал: «И суди (о, Посланник) между ними [иудеями] согласно тому, что ниспослал Аллах (в Коране)», сура «Аль-Маида»/49 аят."],["p","286/2 — Второй аят:"],["p","Всевышний Аллах сказал: «Так суди же среди людей по истине [по справедливости] и не следуй за прихотью (при вынесении решения), а то она сведёт тебя с пути Аллаха [отклонит тебя от Закона Аллаха]», сура «Сад»/26 аят."],["p","287/3 — Третий аят: (2)"],["p","Всевышний Аллах сказал: «А если ты станешь судить (между ними), то суди их беспристрастно: поистине, Аллах любит беспристрастных!», сура «Аль-Маида»/42 аят."],["p","288/4 — Четвертый аят:"],["p","Всевышний Аллах сказал: «Но нет — (Я, Аллах) клянусь твоим (о, Мухаммад) Господом [Самим Собой]! — не уверуют они, пока не сделают тебя судьей (обратившись к тебе самому при твоей жизни, и к твоей Сунне после твоей смерти) в том,"],["p","(1) Общее число аятов, которые Ибн касим привел в книге Судейства — 27 аятов. Автор разъяснил смысл слова «глава» и заменил его на слово «книга», следуя системе установленной учеными ханбалитского мазхаба."]],[["p","(2) Данный аят отсутствет в издании книги «Основы вынесения шариатских постановлений», которая имеется в наличии. Однако он достоверно приводится в его разъяснении «Шариатские постановления» 4/485."],["sc","img/word-92/image104.webp",294,508,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления что запутано между ними [во всех спорных ситуациях], и потом не найдут они в своих душах стеснения [сомнения и неудовлетворённости] к тому, что ты решил, и подчинятся полностью», сура «Ан-Ниса»/65 аят."],["h2","<b>Раздел: Об этикетах судейства</b>"],["p","289/5 — Первый аят:"],["p","Всевышний Аллах сказал: «А кто не судит по тому, что низвёл Аллах, (будучи убеждённым в дозволенности этого), то такие (являются) неверными», сура «Аль-Маида»/44 аят."],["p","290/6 — Второй аят:"],["p","Всевышний Аллах сказал: «А кто не судит по тому, что низвёл Аллах, то такие (являются) беззаконниками», сура «Аль-Маида»/45 аят."],["p","291/7 — Третий аят:"],["p","Всевышний Аллах сказал: «А кто не судит по тому, что низвёл Аллах, такие (являются) непокорными», сура «Аль-Маида»/47 аят."],["p","292/8 — Четвертый аят:"],["p","Всевышний Аллах сказал: «И советуйся с ними о деле (которое требует совета)», сура «Аль Имран»/159 аят."],["sc","img/word-92/image105.webp",295,502,"f"],["c","Книга Судейства"],["h2","<b>Глава: Доля</b>"]],[["p","293/9 — Первый аят:"],["p","Всевышний Аллах сказал: «И сообщи им (о, Салих), что вода поделена между ними [между твоим народом и верблюдицей]: каждое питьё в своё время [один день вся вода для верблюдицы, а в другой день вся вода для людей]», сура «Аль-Камар»/28 аят."],["p","294/10 — Второй аят:"],["p","Всевышний Аллах сказал: «А когда присутствуют при разделе (наследства) родственники (умершего) (у которых нет никаких прав на это имущество), сироты и бедняки, то наделяйте их из этого [дайте немного] (до того, как приступите к дележу имущества между наследниками)», сура «Ан-Ниса»/8 аят."],["h2","<b>Глава: Призывы и явные доказательства</b>"],["p","295/11 — Первый аят:"],["p","Всевышний Аллах сказал: «И всё, чего они потребуют [любое удовольствие и наслаждение]», сура «ЙаСин»/57 аят."],["p","296/12 — Второй аят:"],["p","Всевышний Аллах сказал: «Побуждай к добру (в словах и делах)», сура «Аль-Аараф»/199 аят."],["h2","<b>Глава: Свидетельства</b>"],["p","297/13 — Первый аят:"],["p","Всевышний Аллах сказал: «И пусть записывает между вами (в этом деле) (какой-нибудь) писец по справедливости [не добавляя и не убавляя, и не склоняясь ни к одной из сторон]. И пусть не отказывается писец (когда его попросили об этом) записать так, как научил его Аллах, и пусть он [писец] пишет, и пусть диктует тот, на котором обязательство (по выплате долга) [берущий в долг]."],["p","И пусть он [берущий в долг] остерегается (наказания) Аллаха, Господа своего [пусть говорит правду при диктовке], и пусть не убавляет из него [из долга] ничего. [Пусть не приуменьшает долг ни в количестве, ни в качестве, ни в виде]."],["sc","img/word-92/image106.webp",338,511,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","А если тот, на ком обязательство (по выплате долга), малоумный [одержим или слабоумен] или слаб (умственно или телесно) [не достиг совершеннолетия], или не может сам диктовать [немой и подобный ему], то пусть диктует его опекун [тот, который занимается его делами] (как например, отец, или дед, или брат, или мать и другие) по справедливости [не добавляя и не убавляя]. И возьмите свидетелями (этого договора) двух из мужчин ваших [из числа верующих]. А если не окажется двух мужчин, то — (одного) мужчину и двух женщин, на которых вы [верующие] согласны, как свидетелей [которые достойны, по подавляющему мнению верующих, выступать в качестве свидетелей], чтобы если собьётся [забудет] одна (свидетельница), то напомнила бы ей другая. И пусть не отказываются свидетели, когда их зовут (к тому, чтобы быть свидетелями или чтобы дать свидетельские показания) и пусть не наскучивает вам записывать его [долг] — малым или большим [независимо от величины суммы] — до (известного) срока его. Это [все перечисленные положения] (для вас) — справедливее пред Аллахом [по Его Закону], и прямее [лучше всего как помощь] для свидетельства, и ближе, чтобы вам не сомневаться [чтобы устранить ваши сомнения относительно возврата долга, его размера и срока]."]],[["p","Разве только, если это будет текущей [происходящей в данный момент] торговлей [покупкой или продажей], которую вы ведёте между собой, — тогда на вас не будет греха, если не запишете этого [торговлю]», сура «Аль-Бакара»/282 аят."],["p","298/14 — Второй аят:"],["p","Всевышний Аллах сказал: «И берите свидетелей [это желательно], когда (между собой) заключаете торговые сделки (чтобы не возникало споров и раздоров). (Свидетелям и писцу обязательно исполнять всё надлежащим образом). И не должен причиняться вред ни писцу и ни свидетелю [участники договора о долге не должны доставлять неприятности писцу и свидетелю] (и также нельзя писцу и свидетелю причинять вред тому, кто нуждается в их записи и свидетельстве); а если вы сделаете (это) [если причините вред] (кому-либо), то это [причинение вреда] (будет) непокорностью вашей [выходом из повиновения Аллаху]. И остерегайтесь (наказания) Аллаха [выполняйте то, что Он повелел и прекратите совершать то, что Он запретил]; И учит вас Аллах (тому, в чём для вас польза в этом мире и в Вечной жизни), и Аллах о всякой вещи [обо всём] знает!», сура «Аль-Бакара»/282 аят."],["p","299/15 — Третий аят:"],["p","Всевышний Аллах сказал: «А (если должник не признаёт своего долга, то вы свидетели) не скрывайте свидетельства (ни полностью и ни частично [уклоняясь назвать количество, качество]), а кто скроет его [свидетельство], то он — тот, у кого сердце грешно [вероломный грешник]», сура «Аль-Бакара»/283 аят."],["p","300/16 — Четвертый аят:"],["p","Всевышний Аллах сказал: «Будьте придерживающимися справедливости [говорите истину], свидетельствуя пред Аллахом, даже если (это свидетельство будет) против вас самих, или (ваших) родителей, или (ваших) близких родственников», сура «Ан-Ниса»/135 аят."],["sc","img/word-92/image107.webp",295,503,"f"],["c","Книга Судейства"]],[["p","301/17 — Пятый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Будьте придерживающимися (справедливости) [говорите истину] ради Аллаха [желая обрести Его довольство], свидетельствуя беспристрастно. И пусть не втянет [не подтолкнёт] вас в грех злоба (по отношению) к (каким-либо) людям на то, что вы поступите несправедливо. Будьте справедливы, это — ближе к остережению [к боязни Аллаха], и остерегайтесь (наказания) Аллаха, — (ведь) поистине, Аллах сведущ в том, что вы делаете (и воздаст вам по вашим деяниям)», сура «Аль-Маида»/8 аят."],["p","302/18 — Шестой аят:"],["p","Всевышний Аллах сказал: «Кроме только тех, кто свидетельствует об истине, будучи знающими [обладают заступничеством ангелы и пророк Ииса, но они смогут заступиться только за тех, за кого Аллах дозволит заступничество]», сура «Аз-Зхруф», 86 аят."],["p","303/19 — Седьмой аят:"],["p","Всевышний Аллах сказал: «И отстраняйтесь наилживых речей [измышлений против Аллаха, многобожия и лжесвидетельства]», сура «Аль-Хадж»/30 аят."],["h2","<b>Раздел: О количестве свидетелей</b>"],["p","304/20 — Первый аят:"],["p","Всевышний Аллах сказал: «Почему бы им [обвиняющим в совершении прелюбодеяния] не привести четырех (справедливых) свидетелей для этого [в подтверждении своих слов]? А если они не приведут свидетелей, то они перед Аллахом являются лжецами», сура «Ан-Нур»/13 аят."],["p","305/21 — Второй аят:"],["p","Всевышний Аллах сказал: «И возьмите свидетелями (этого договора) двух из мужчин ваших [из числа верующих]. А если не окажется двух мужчин, то — (одного) мужчину и двух женщин, на которых вы [верующие] согласны, как свидетелей [которые достойны, по подавляющему мнению верующих, выступать в качестве свидетелей], чтобы если собьётся [забудет] одна (свидетельница), то напомнила бы ей другая», сура «Аль-Бакара»/282 аят."],["sc","img/word-92/image108.webp",331,525,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"]],[["p","306/22 — Третий аят:"],["p","Всевышний Аллах сказал: «Призовите в свидетели двух справедливых (мужчин) из числа вас [верующих] и (о, свидетели) исполняйте свидетельство (только) ради Аллаха (а не для чего-либо другого). Этим [тем, что Аллах повелел] увещается тот, кто верует в Аллаха и в Последний день [в День Суда]», сура «Ат-Талак»/2 аят."],["p","307/23 — Четвертый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Свидетельством между вами, когда предстанет к кому-нибудь из вас смерть [появятся признаки того, что человек умрёт], в момент завещания (если он его оставляет) (должны быть) двое справедливых из вас [из числа верующих] или два других [неверующих] не из вас (при необходимости и когда нет свидетелей-мусульман), когда вы странствуете по земле [находитесь в пути] и вас постигнет несчастие смерти», сура «Аль-Маида»/106 аят."],["h2","<b>Глава: Подтверждение</b>"],["p","308/24 — Первый аят:"],["p","Всевышний Аллах сказал: «И (упомяни, о Посланник, о том) как взял Аллах завет [договор, подкреплённый клятвой] со (всех) пророков [заключал с каждым пророком]: «Какое бы Я ни даровал вам писание и мудрость, (но) затем (когда) придёт к вам (от Аллаха) (следующий) посланник, подтверждающий истинность того, что с вами, то вы, непременно и обязательно, уверуете в него [в нового посланника] и будете помогать ему». Сказал Он: «Подтверждаете ли вы (о, пророки) и принимаете ли на этом (условии) Мою ношу [этот завет]?» Они [пророки] сказали: «Мы подтверждаем». (Аллах) сказал: «Будьте же свидетелями, и Я (тоже) буду с вами из (числа) свидетелей», сура «Аль Имран»/81 аят."],["p","309/25 — Второй аят:"],["p","Всевышний Аллах сказал: «Но (есть и) другие (из числа жителей Медины и её окрестностей), (которые) признались в своих грехах (сожалели о содеянном и обратились к Аллаху с покаянием): они смешивали праведное дело и другое — плохое», сура «Ат-Тауба»/102 аят."],["sc","img/word-92/image109.webp",305,503,"f"],["c","Книга Судейства"]],[["p","310/26 — Третий аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Будьте придерживающимися справедливости [говорите истину], свидетельствуя пред Аллахом, даже если (это свидетельство будет) против вас самих, или (ваших) родителей, или (ваших) близких родственников. Будь тот (против которого свидетельствуют) богатым или бедным, то (ведь) Аллах ближе к ним обоим (чем вы) [Он знает в чём для них благо, поэтому доверьте Ему их дело]. И не следуйте же за прихотью, чтобы не отступить от справедливости», сура «Ан-Ниса»/135 аят."],["p","311/2 –Четвертый аят:"],["p","Всевышний Аллах сказал: «И вот, Господь твой выводил (на протяжении истории человечества) из потомков Адама, из спин их, их потомство и заставил их засвидетельствовать о самих себе: «Не Я ли — ваш Господь?» Они сказали: «Да, мы свидетельствуем (что Ты — наш Господь)». (Это) — для того, чтобы вы не сказали в День Воскресения: «Поистине, мы были беспечными к этому», сура «Аль-Аараф»/172 аят."],["sep",""],["sc","img/word-92/image110.webp",335,503,"f"],["p","Одно из выдающихся дел обладателя его королевского высочества Принца Султана ибн Абдуль-Азиза Аль Сауда, наследного принца, вице-премьер-министра, министра обороны и авиации — его инициатива по проведению конкурса на знание Благородного Корана, который стал известен под названием: «Международная премия принца Султана по заучиванию Благородного Корана среди военнослужащих»."],["p","Сегодня его высочество своим благородным наблюдением украсил издание серии публикаций под названием «Коранические знания», внеся свой вклад в увеличение приносимой ею пользы, проявляя усердие в служении Благородному Корану и желая распространения благого знания."],["p","Тема этих публикаций — связанные с Кораном науки, такие как: тафсир, его основы и правила, коранические знания, таджвид, кырааты, с целью внедрения их в программу конкурса."]],[["p","Да возблагодарит Аллах его королевское высочество принца Султана ибн Абдуль-Азиза Аль Сауда за его неустанное стремление и большое внимание к заботе о Благородном Коране! И да сделает его из числа тех, кто внес свой вклад в изучение Корана и обучение ему! И да сделает Аллах пользу от тех его деяний, которые он совершил на пути служения Корану, — непрекращающейся, ведь Аллах оказывает содействие в благом!"],["h2","<b><i>Международная премия принца Султана по заучиванию Благородного Корана среди военнослужащих</i></b>"]]];
